import { driver, expect } from '@wdio/globals';
import { byText, byTextContains, tapText } from '../../helpers/ui.ts';
import { ensureAppReady, isLoggedIn, logout, login } from '../../helpers/app.ts';
import { skipWith, shown } from '../_lib/app-0710.ts';

const GONE = 'החשבון נוצר ונשמר. אין צורך להירשם שוב, גם אם תסגור את האפליקציה עכשיו.';
const POINTS = ['התאמה אוטומטית לפי מיקום וזמן', 'תזכורות חכמות לזמני תפילה', 'מעקב אחר התקדמות והרגלים'];

describe('Регистрация: экран «יש! יצרת חשבון»', () => {
  it('RG-05 Регистрация нового аккаунта (человек) → «שלח» → «יש! יצרת חשבון»: два текста, 3 пункта, без «החשבון נוצר ונשמר…», «בואו נתקדם» → «תאריך לידה» → (человек) главная #3298e56c #f688d2b0 @data @manual-check', async function () {
    if (process.env.QA_REG_MANUAL !== '1') skipWith(this, 'регистрация нового номера с OTP — вручную; запуск с QA_REG_MANUAL=1 и человеком у телефона');
    this.timeout(1200000);
    try {
      await logout();
      console.log('[RG-05] @manual-check: зарегистрируйте НОВЫЙ аккаунт: «יצירת חשבון» → «שלח» (сразу «יש! יצרת חשבון», #f688d2b0). Тест ждёт до 15 минут…');
      await driver.waitUntil(async () => (await shown(byText('יש! יצרת חשבון'))) || (await shown(byText('תאריך לידה'))),
        { timeout: 900000, interval: 3000, timeoutMsg: 'не дождались «יש! יצרת חשבון» после «שלח»' });

      // Экран «יש! יצרת חשבון».
      await expect(byText('יש! יצרת חשבון')).toBeDisplayed({ wait: 20000 });
      await expect(byTextContains('עכשיו נעשה התאמה אישית וסיימנו')).toBeDisplayed();
      await expect(byTextContains(GONE)).not.toBeDisplayed();
      await expect(byTextContains('החשבון נוצר ונשמר')).not.toBeDisplayed();
      for (const p of POINTS) await expect(byTextContains(p)).toBeDisplayed();

      // «בואו נתקדם» → «תאריך לידה» (#f688d2b0); настройку до главной проходит человек.
      await tapText('בואו נתקדם');
      await expect(byText('תאריך לידה')).toBeDisplayed({ wait: 30000 });
      console.log('[RG-05] @manual-check: пройдите настройку до главной («מוכנים להתחיל!» → «בוא נתחיל»), не через «חזרה». Тест ждёт до 15 минут…');
      await driver.waitUntil(isLoggedIn, { timeout: 900000, interval: 3000, timeoutMsg: 'настройка не доведена до главной' });
    } finally {
      try { await logout(); await login('USER1'); } catch (e) { console.warn('[RG-05] вернуть USER1 вручную', e); await ensureAppReady().catch(() => {}); }
    }
  });
});
